import React, { useState } from "react";
import "../styles/contactfinder.css";

function ContactFinder() {

  const [city, setCity] = useState("");
  const [result, setResult] = useState("");

  const findContact = () => {

    if (city === "Lahore") {
      setResult("Legal Helpline: 042-111-111-111");
    }
    else if (city === "Karachi") {
      setResult("Legal Helpline: 021-222-222-222");
    }
    else if (city === "Islamabad") {
      setResult("Legal Helpline: 051-333-333-333");
    }
    else {
      setResult("No contact found for this city.");
    }

  };

  return (
    <div className="contactfinder-container">

      <h1>Contact Finder</h1>

      <div className="contactfinder-form">

        <label>Select Your City</label>

        <select
          value={city}
          onChange={(e) => setCity(e.target.value)}
        >
          <option value="">-- Select City --</option>
          <option value="Lahore">Lahore</option>
          <option value="Karachi">Karachi</option>
          <option value="Islamabad">Islamabad</option>
        </select>

        <button onClick={findContact}>
          Find Contact
        </button>

        {result && (
          <h2 className="result">
            {result}
          </h2>
        )}

      </div>

    </div>
  );
}

export default ContactFinder;
